function drawAngelWings(e, cx, cy, dark, sc) { const x = e.x - cx, y = e.y - cy - (e.z || 0), s = sc || 1, fl = Math.sin(G.t * 6 + e.x) * 3 * s; ctx.fillStyle = dark ? 'rgba(30,10,50,0.9)' : 'rgba(250,250,255,0.92)'; ctx.strokeStyle = dark ? '#8a5aff' : '#c8d8f0'; ctx.lineWidth = 1;
  for (const sd of [-1, 1]) { ctx.beginPath(); ctx.moveTo(x + sd * 3 * s, y - 20 * s); ctx.quadraticCurveTo(x + sd * 22 * s, y - 38 * s - fl, x + sd * 26 * s, y - 14 * s); ctx.quadraticCurveTo(x + sd * 14 * s, y - 18 * s, x + sd * 3 * s, y - 12 * s); ctx.fill(); ctx.stroke(); } }
{ const _de = drawEnt; drawEnt = function (e, cx, cy) { const L = e.type === 'mob' && e.def && e.def.art && e.def.art[0] === 'hum' && HLOOKS[e.def.art[1]]; if (L && L.wings && !e.dying) drawAngelWings(e, cx, cy, L.wings === 2, e.scale || 1); if (e.type === 'npc' && e.def && e.def.wings) drawAngelWings(e, cx, cy, false, 1); return _de(e, cx, cy); }; }
