q('q33', { n: L2('La Escalera Rota', 'The Broken Stairway'), main: 1, giver: 'mira', lv: 200, pre: 'q32', desc: L2('Mira abre por fin las páginas selladas: arriba, sobre las nubes, existió Celestia. Para subir hace falta un barco que vuele. Busca a la ingeniera Celestina en Puerto Coral.', 'Mira finally opens the sealed pages: above the clouds, Celestia existed. To get up there you need a ship that flies. Find the engineer Celestina in Puerto Coral.'), obj: [{ t: 'talk', npc: 'ingeniera', txt: L2('Habla con Celestina en Puerto Coral', 'Talk to Celestina in Puerto Coral') }], rew: { xp: 9000000, gold: 200000 }, offer: L2('El Desatado no mentía. El libro habla de cinco islas sobre las nubes… y de lo que duerme en la más alta.', 'The Unbound wasn\'t lying. The book speaks of five islands above the clouds… and of what sleeps on the highest one.'), done: L2('¿Un barco que vuele? ¡Llevo toda la vida esperando a alguien que me lo pida!', 'A ship that flies? I\'ve waited my whole life for someone to ask me that!') });
