q('q35', { n: L2('Sobre las Nubes', 'Above the Clouds'), main: 1, giver: 'ingeniera', lv: 201, pre: 'q34', desc: L2('Vuela a Celestia en la Aeronave y habla con quien te reciba en la Isla del Alba.', 'Fly to Celestia in the Airship and talk to whoever greets you on the Isle of Dawn.'), obj: [{ t: 'talk', npc: 'serafina', txt: L2('Encuentra a los Alados en la Isla del Alba', 'Find the Winged on the Isle of Dawn') }], rew: { xp: 10000000, gold: 250000 }, offer: L2('Agárrate fuerte. La subida es lo peor… o lo mejor.', 'Hold on tight. The climb is the worst part… or the best.'), done: L2('Un hilo de abajo… por fin. Te esperábamos, aunque no sabíamos que serías tú.', 'A thread from below… at last. We were waiting for you, though we didn\'t know it would be you.') });
q('q36', { n: L2('El Rey de los Grifos', 'The King of Griffins'), main: 1, giver: 'serafina', lv: 203, pre: 'q35', desc: L2('Aurion, el Rey de los Grifos, protegía la Isla del Alba. Nihil le ha susurrado y ahora ataca a los suyos. Libéralo.', 'Aurion, King of Griffins, protected the Isle of Dawn. Nihil has whispered to him and now he attacks his own. Free him.'), obj: [{ t: 'boss', b: 'rey_grifo_aurion' }], rew: { xp: 11000000, gold: 300000, items: [['pluma_alba', 6]] }, offer: L2('Aurion era nuestro guardián. Ya no reconoce a nadie.', 'Aurion was our guardian. He no longer recognizes anyone.'), done: L2('Al caer, sus ojos volvieron a ser dorados. Gracias.', 'As he fell, his eyes turned golden again. Thank you.') });
q('q37', { n: L2('Las Aureolas Perdidas', 'The Lost Halos'), main: 1, giver: 'serafina', lv: 206, pre: 'q36', desc: L2('Cada isla esconde un templo sellado. Reúne las 3 aureolas de la Isla del Alba y abre su templo oculto.', 'Each island hides a sealed temple. Gather the 3 halos of the Isle of Dawn and open its hidden temple.'), obj: [{ t: 'flag', f: 'temple1', txt: L2('Abre el templo oculto del Alba', 'Open the hidden temple of Dawn') }], rew: { xp: 12000000, gold: 300000 }, offer: L2('Las aureolas guardan los nombres de los primeros Alados. Juntas abren lo que escondimos.', 'The halos keep the names of the first Winged. Together they open what we hid.'), done: L2('Ese templo guardaba nuestra memoria. Ahora también es tuya.', 'That temple kept our memory. Now it\'s yours too.') });
