q('q40', { n: L2('El Jardín que Canta', 'The Singing Garden'), main: 1, giver: 'serafina', lv: 221, pre: 'q39', desc: L2('Seraviel, el arcángel que cuidaba el Jardín Celeste, ha caído ante Nihil. Detenlo antes de que el jardín deje de cantar.', 'Seraviel, the archangel who tended the Celestial Garden, has fallen to Nihil. Stop him before the garden stops singing.'), obj: [{ t: 'boss', b: 'seraviel' }], rew: { xp: 16000000, gold: 400000, items: [['aureola_rota', 6]] }, offer: L2('Seraviel era el mejor de nosotros. Por eso Nihil lo quería.', 'Seraviel was the best of us. That\'s why Nihil wanted him.'), done: L2('Sus últimas palabras fueron tu nombre. No sé cómo lo sabía.', 'His last words were your name. I don\'t know how he knew it.') });
q('q41', { n: L2('El Telar Dormido', 'The Sleeping Loom'), main: 1, giver: 'serafina', lv: 229, pre: 'q40', desc: L2('En la Isla del Telar queda alguien: Lys, la Última Tejedora. Habla con ella y destruye al Telar Viviente que Nihil ha despertado.', 'Someone remains on the Isle of the Loom: Lys, the Last Weaver. Talk to her and destroy the Living Loom Nihil has awakened.'), obj: [{ t: 'talk', npc: 'tejedora_ultima', txt: L2('Habla con Lys en la Isla del Telar', 'Talk to Lys on the Isle of the Loom') }, { t: 'boss', b: 'telar_viviente' }], rew: { xp: 18000000, gold: 450000, items: [['hilo_estelar', 6]] }, offer: L2('El Telar teje vidas. Si Nihil lo controla, tejerá silencio.', 'The Loom weaves lives. If Nihil controls it, it will weave silence.'), done: L2('El Telar descansa. Ahora puedo enseñarte a despertar tu propio hilo.', 'The Loom rests. Now I can teach you to awaken your own thread.') });
